import{_ as t,l as R,o as e,c as E,v as r,p as o,x as i,d as n,i as s,S as p}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"隐含回购利率","description":"","frontmatter":{"title":"隐含回购利率","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/implied-repo.md","filePath":"quant/implied-repo.md","lastUpdated":1789023840000}'),d={name:"quant/implied-repo.md"};function B(A,a,h,c,I,u){const l=R("Mermaid");return e(),E("div",null,[a[1]||(a[1]=r('<h1 id="隐含回购利率" tabindex="-1">隐含回购利率 <a class="header-anchor" href="#隐含回购利率" aria-label="Permalink to &quot;隐含回购利率&quot;">​</a></h1><div class="epigraph"><p>把债券持有到期货交割、用发票金额回收本金，中间的内部收益率就是隐含回购；它高于实际融资则买券空期货，低于则反向，前提是你交的真是 CTD。</p><footer>—— Burghardt, Belton, Lane &amp; McVey, The Treasury Bond Basis；对照 Hull 的期现持有成本</footer></div><p>隐含回购利率（implied repo rate, IRR）是债券期货基差交易的报价语言：给定现货净价、应计、转换因子、期货价格、交割日与期间票息，解出「若用该券交割，这笔期现的融资利率是多少」。它把<a href="/quant/ctd-cheapest">最便宜可交割</a>的排序从「净基差谁最小」改写成「谁给出最高的隐含回购」——对空头期货、多头现券的正向期现，IRR 最高的券通常就是 CTD。Burghardt 的体系把 IRR 与实际回购（term repo 或隔夜滚动）比较，差是扣掉交割期权之后还能否执行的边缘。Hull 的商品持有成本是同一会计在物理仓储上的版本；债券把仓储换成回购市场。没有真实可借的券与可成交的期货，IRR 只是屏幕上的内部收益率。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>忽略一些惯例细节，从 \\(t\\) 持有到交割 \\(T\\)、期间收到票息 \\(C\\) 的 IRR 满足把流出（买券）与流入（发票金额加票息再投资假设）配平。实务公式在各交易所通告里写死，日计数与应计不能用错。问题不在求解，而在：IRR 用的是当前 CTD 的发票公式，若交割时 CTD 已切换，你实现的融资利率不是开仓时算的那个 IRR。Hemler 的交割期权、Kane–Marcus 的万能牌，都会使期货比「纯 CTD 远期」便宜，从而把屏幕 IRR 抬高——看起来正向期现很美，其实你在卖期权。比较 IRR 与实际 repo 时，必须从差里减去这些期权的公允，剩下的才是可讨论的错误定价。</p><p>第二层是 repo 本身的期限与特殊性。屏幕 IRR 常按到交割日的期限算；实际融资可能是隔夜滚动，路径上 specialness 与一般抵押品（GC）利差会变。开仓时 IRR 高于 GC 十个基点，持有期内券变 special，滚动融资变贵，实现利润消失。反向交易（卖券买期货）需要能借到券，借券费直接进入实际融资。商品上没有 IRR 这个名字，但租借率与便利收益扮演同类角色，见 Working 与<a href="/quant/cash-and-carry">期现套利</a>。</p><h3 id="irr-不是债券到期收益率" tabindex="-1">IRR 不是债券到期收益率 <a class="header-anchor" href="#irr-不是债券到期收益率" aria-label="Permalink to &quot;IRR 不是债券到期收益率&quot;">​</a></h3><p>到期收益率把债券的全部票息与本金折到无穷或到期；IRR 只把现金流计算到期货交割，本金回收来自发票，不是来自发行人。把 IRR 与 YTM 比高低没有意义。IRR 与 GC repo 比才有意义，且要对齐担保品、期限、是否可提前召回。失败交割会打断「发票一定在 \\(T\\) 到账」的假设，IRR 的分母还在、分子变成不确定。这是结算制度风险，不是利率观点。</p><p><span class="marginnote">用结算价算 IRR、用买卖价成交，会把一整段价差算进「隐含回购优势」。应在可执行的债券买价（或卖价）与期货卖价（或买价）上算两条 IRR，只有带外的那一侧才允许开仓。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对篮子逐券：取可成交现货与期货，代入该市场的发票公式，解 IRR。排序得到最高 IRR 的券，检查其可借性、发行量、是否接近交割月持仓限制。将最高 IRR 与该券 term repo 报价比较，扣掉估计的交割期权（用篮内离散度与波动，或用净基差的期权部分）。仅当正向期现的净边缘覆盖债券有效价差、期货价差、清算费用与<a href="/quant/futures-margin">保证金</a>占用后仍为正，才开买券空期货。反向同理，边缘要对着借券费。</p><p>风险情景：平行加扭转使 CTD 切换，重算实现 IRR；repo 利差扩大；交割失败；期货停板而债券仍在交易。对冲比用 DV01 而不是 CF，切换后重平衡。容量取 CTD 可获得量、repo 市场深度与期货交割限额的最小者。拥挤的基差账会把 IRR–repo 差压到刚好覆盖最优执行者的成本，次优者的净期望为负——与指数套利同一逻辑。</p><h3 id="从-irr-回到商品语言" tabindex="-1">从 IRR 回到商品语言 <a class="header-anchor" href="#从-irr-回到商品语言" aria-label="Permalink to &quot;从 IRR 回到商品语言&quot;">​</a></h3><p>商品的「隐含仓储」可以把期货升水拆成融资加仓储加便利收益残差。IRR 是债券版的隐含融资：升水（或基差）里属于资金的那一块被显式解出，残差留给期权与错误定价。Erb–Harvey 在商品上强调展期不是票息；这里对称：IRR 高于 GC 不是「无风险多赚一截利息」，除非期权与执行都已扣除。Working 的仓储理论提醒残差可以持久（便利收益）；债券上对应的持久残差是交割期权与 specialness，不是免费 alpha。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>无套利机制：IRR 显著高于实际融资且期权价值不够解释时，买券空期货，交割或提前平仓，把差变成持有期收益。资本进入压低期货或抬高现券，IRR 回落。反向则卖券买期货。收敛日是交割结算，盯市路径上期货腿每日兑付，债券腿的盈亏在市值与融资里，现金错配见保证金一文。切换机制：市场利率变动改变因子残差排序，你的券不再给出最高 IRR，期货开始跟踪新 CTD，基差头寸出现方向性。这是债券日历里最常见的「模型还对、账已经亏」的来源。</p><p>Repo 机制：CTD 需求使该券 special，多头持券的融资变便宜，IRR 与实际融资的差在持有端改善、在建立端恶化——后来者更难做。这是容量的内生收窄。清算与保证金使杠杆在波动上升时下降，同样的 IRR 差在危机里不可按原名义执行。</p><h3 id="破裂-切换、special、fails、日历" tabindex="-1">破裂：切换、special、fails、日历 <a class="header-anchor" href="#破裂-切换、special、fails、日历" aria-label="Permalink to &quot;破裂：切换、special、fails、日历&quot;">​</a></h3><p>CTD 切换使开仓 IRR 作废。券突然 special 或变为 general，滚动融资跳。大规模 fails 使发票到账日不再确定。交割日历、假期与券息日让日计数与再投资假设出错，几个基点的「优势」可以只是惯例。篮子调整（新发债进入合格清单）在公告日重估所有 IRR。非美合约的发票公式若含不同的应计或交割选择，照搬美债 IRR 会得到错误的 CTD。</p><p><span class="marginnote">把历史平均「IRR 减 GC」当成策略的期望，忽略了期权价值随篮内离散度变化。低波动、CTD 遥遥领先时，差更接近真的期现；高波动、两只券打平时，差大部分是 Hemler 期权。无条件均值把两种状态混在一起。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要用中间价 IRR 下单。不要用 YTM 或政策利率替代实际 repo。不要在交割月临近仍按非交割月保证金去加杠杆。成本含券与期货的有效价差、repo 买卖、失败惩罚、切换后的再套保冲击。容量不是期货 OI，是 CTD 的可融量。与商品<a href="/quant/roll-yield">展期收益</a>不要类比成「收息」：IRR 是内部收益率报价，实现仍依赖交割与融资路径。</p><p>报告应并排：可执行 IRR、term repo、期权调整后边缘、当前与次 CTD、DV01 对冲比、保证金情景。Burghardt 提供会计；Hemler 与 Kane–Marcus 提供期权；Hull 提供与商品持有成本的对照。缺期权调整的 IRR 策略，是在无补偿地卖空交割选择权。</p><p><span class="marginnote">反向期现（IRR 过低）在券不可借时只是一句空话。屏幕上出现「惊人的低 IRR」，往往是 bid 已消失或只能卖出很小规模。可执行 IRR 必须用真实的债券卖价与可借确认。</span></p>',24)),(e(),o(p,null,{default:i(()=>[s(l,{id:"mermaid-70",class:"mermaid",graph:"flowchart%20TD%0A%20%20BOND%5B%22%E5%8F%AF%E6%88%90%E4%BA%A4%E5%80%BA%E5%88%B8%E4%BB%B7%22%5D%20--%3E%20IRR%5B%22%E9%9A%90%E5%90%AB%E5%9B%9E%E8%B4%AD%20IRR%22%5D%0A%20%20FUT%5B%22%E5%8F%AF%E6%88%90%E4%BA%A4%E6%9C%9F%E8%B4%A7%E4%BB%B7%22%5D%20--%3E%20IRR%0A%20%20CF%5B%22%E5%9B%A0%E5%AD%90%E3%80%81%E5%BA%94%E8%AE%A1%E3%80%81%E7%A5%A8%E6%81%AF%E3%80%81%E4%BA%A4%E5%89%B2%E6%97%A5%22%5D%20--%3E%20IRR%0A%20%20REPO%5B%22%E5%AE%9E%E9%99%85%20repo%20%2F%20%E5%80%9F%E5%88%B8%22%5D%20--%3E%20EDGE%5B%22IRR%20%E5%87%8F%E8%9E%8D%E8%B5%84%E5%87%8F%E6%9C%9F%E6%9D%83%22%5D%0A%20%20OPT%5B%22CTD%20%E5%88%87%E6%8D%A2%E4%B8%8E%E4%B8%87%E8%83%BD%E7%89%8C%22%5D%20--%3E%20EDGE%0A%20%20IRR%20--%3E%20EDGE%0A%20%20EDGE%20--%3E%7C%22%E6%AD%A3%E5%90%91%E5%B8%A6%E5%A4%96%E4%B8%94%E5%8F%AF%E4%BA%A4%E5%89%B2%22%7C%20CAC%5B%22%E4%B9%B0%E5%88%B8%E7%A9%BA%E6%9C%9F%E8%B4%A7%22%5D%0A%20%20EDGE%20--%3E%7C%22%E5%8F%8D%E5%90%91%E5%B8%A6%E5%A4%96%E4%B8%94%E5%8F%AF%E5%80%9F%22%7C%20REV%5B%22%E5%8D%96%E5%88%B8%E4%B9%B0%E6%9C%9F%E8%B4%A7%22%5D%0A%20%20CAC%20--%3E%20PATH%5B%22%E7%9B%AF%E5%B8%82%20%2B%20%E6%BB%9A%E5%8A%A8%E8%9E%8D%E8%B5%84%20%2B%20%E6%88%96%E6%9C%89%E5%88%87%E6%8D%A2%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>隐含回购是债券持有至期货交割的内部收益率，用于 CTD 排序并与实际回购比较；它不是 YTM。</li><li>屏幕 IRR 含交割期权溢价；须用 Burghardt 会计加 Hemler / Kane–Marcus 期权调整后才谈错误定价。</li><li>执行依赖可借券、可成交期货与交割路径；切换与 specialness 使开仓 IRR 不必等于实现融资。</li><li>容量由 CTD 可融量决定；保证金与 fails 是路径破裂。</li><li>出处：Burghardt, Belton, Lane and McVey, <em>The Treasury Bond Basis</em>；Hemler, <em>Journal of Finance</em>, 1990；Kane and Marcus, <em>Journal of Finance</em>, 1986；Hull, <em>Options, Futures, and Other Derivatives</em>；持有成本对照 Working, <em>AER</em>, 1949。</li></ul>',2))])}const C=t(d,[["render",B]]);export{D as __pageData,C as default};
